package app.launcherin.tv;
import android.content.Context;import android.graphics.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.annotation.GraphicsMode;import org.schabi.newpipe.extractor.Image;import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk={34,35}) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class LauncherinArtworkQualityTest {
 Context c;@Before public void setup(){c=RuntimeEnvironment.getApplication();}
 @Test public void selectsHighestResolutionIndependentlyOfProviderOrder(){Image low=new Image("https://example.org/low.jpg",60,60,Image.ResolutionLevel.LOW),high=new Image("https://example.org/high.jpg",640,640,Image.ResolutionLevel.HIGH),medium=new Image("https://example.org/medium.jpg",240,240,Image.ResolutionLevel.MEDIUM);assertEquals(high.getUrl(),LauncherinMusicSource.image(Arrays.asList(high,medium,low)));assertEquals(high.getUrl(),LauncherinMusicSource.image(Arrays.asList(low,medium,high)));}
 @Test public void honorsEstimatedQualityWhenDimensionsAreUnknown(){Image low=new Image("https://example.org/low.jpg",-1,-1,Image.ResolutionLevel.LOW),high=new Image("https://example.org/high.jpg",-1,-1,Image.ResolutionLevel.HIGH);assertEquals(high.getUrl(),LauncherinMusicSource.image(Arrays.asList(low,high)));assertEquals("",LauncherinMusicSource.image(Collections.emptyList()));}
 @Test public void upgradesMusicCdnSizesAndKeepsOriginalFallback(){String source="https://lh3.googleusercontent.com/album=w60-h60-l90-rj";List<String> choices=LauncherinArtworkQuality.candidates(source,320,240);assertEquals("https://lh3.googleusercontent.com/album=w640-h640-l90-rj",choices.get(0));assertEquals(source,choices.get(choices.size()-1));assertEquals("https://i1.sndcdn.com/artworks-example-t500x500.jpg",LauncherinArtworkQuality.candidates("https://i1.sndcdn.com/artworks-example-large.jpg",320,240).get(0));}
 @Test public void doesNotRewriteForeignHostsOrTurnImageUrlsIntoExecutableRoutes(){for(String source:new String[]{"https://example.org/album=w60-h60-l90-rj","https://lh3.googleusercontent.com.evil.invalid/album=w60-h60-l90-rj","https://lh3.googleusercontent.com@evil.invalid/album=w60-h60-l90-rj"})assertEquals(Collections.singletonList(source),LauncherinArtworkQuality.candidates(source,320,240));}
 @Test public void oldVideoThumbnailHasAnHdAndOriginalFallbackWithoutDuplicateRequests(){String source="https://i.ytimg.com/vi/abcdefghij0/default.jpg";List<String> urls=LauncherinArtworkQuality.candidates(source,480,480);assertEquals("https://i.ytimg.com/vi/abcdefghij0/maxresdefault.jpg",urls.get(0));assertEquals("https://i.ytimg.com/vi/abcdefghij0/hqdefault.jpg",urls.get(1));assertEquals(source,urls.get(2));assertEquals(1,LauncherinArtworkQuality.sample(1280,720,480,480));assertEquals(2,LauncherinArtworkQuality.sample(1280,720,320,240));}
 private void cached(String url,int width,int height,int color,boolean legacy)throws Exception{File dir=new File(c.getCacheDir(),"player-art");dir.mkdirs();File f=new File(dir,LauncherinMusicLibrary.hash(((legacy?"":"art-v2:")+url).getBytes(StandardCharsets.UTF_8))+".img");Bitmap b=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);b.eraseColor(color);try(OutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.JPEG,90,out);}b.recycle();}
 @Test public void storedLowResolutionCacheCannotOverrideTheNewHighQualityVariant()throws Exception{String source="https://lh3.googleusercontent.com/album=w60-h60-l90-rj",high=LauncherinArtworkQuality.candidates(source,320,240).get(0);cached(source,60,60,Color.RED,true);cached(high,640,640,Color.BLUE,false);Bitmap image=LauncherinPlayerImages.load(c,source,320,240);try{assertTrue(image.getWidth()>=320);int color=image.getPixel(image.getWidth()/2,image.getHeight()/2);assertTrue(Color.blue(color)>Color.red(color));}finally{image.recycle();}}
 @Test public void aTinyHdPlaceholderFallsBackToTheActualAvailableCover()throws Exception{String source="https://i.ytimg.com/vi/abcdefghij0/hqdefault.jpg";List<String> choices=LauncherinArtworkQuality.candidates(source,320,240);cached(choices.get(0),120,90,Color.BLACK,false);cached(source,480,360,Color.GREEN,false);Bitmap image=LauncherinPlayerImages.load(c,source,320,240);try{assertTrue(image.getWidth()>=320);assertTrue(Color.green(image.getPixel(image.getWidth()/2,image.getHeight()/2))>100);}finally{image.recycle();}}
 @Test public void decodingDoesNotEnlargeASmallOriginalOrDiscardTheNeededCropResolution()throws Exception{String source="https://example.org/album.jpg";cached(source,1280,720,Color.CYAN,false);Bitmap image=LauncherinPlayerImages.load(c,source,480,480);try{assertTrue(image.getHeight()>=480);assertTrue((long)image.getWidth()*image.getHeight()<=1_048_576);}finally{image.recycle();}}
}
